/**
 * A tolerant, read-only `.env` parser for checks (`env:check`, `doctor`, the production guard).
 *
 * It accepts the dotenv dialect generated by devkit and written by hand: `KEY=value`, optional
 * `export ` prefixes, single/double-quoted values (double quotes understand `\n`, `\"`, `\\`),
 * comments on their own line, and ` #` comments after unquoted values. It never throws: a line it
 * cannot read is reported as `invalid` with its line number, so a check can point at it.
 * (Writing env files is devkit's job; this module never writes.)
 *
 * @module
 */
import { existsSync, readFileSync } from 'node:fs'

/** One variable as found in a file. */
export interface EnvEntry {
  readonly key: string
  readonly value: string
  /** 1-based line number. */
  readonly line: number
}

/** The parsed file. */
export interface EnvFile {
  /** Last definition wins, as in dotenv. */
  readonly entries: ReadonlyMap<string, EnvEntry>
  /** Every assignment in file order, duplicates included. */
  readonly all: readonly EnvEntry[]
  /** Keys defined more than once. */
  readonly duplicates: readonly string[]
  /**
   * Lines that are neither blank, comments nor assignments, by line number only: their text is
   * never kept, because a malformed line is often a pasted secret.
   */
  readonly invalid: readonly { readonly line: number }[]
}

/** Valid variable names: what shells and process managers accept everywhere. */
export const ENV_KEY: RegExp = /^[A-Za-z_][A-Za-z0-9_]*$/

const ASSIGNMENT = /^\s*(?:export\s+)?([^=\s]+)\s*=(.*)$/

function unquote(raw: string): string {
  const value = raw.trim()
  const quote = value[0]
  if ((quote === '"' || quote === "'") && value.length >= 2) {
    const end = value.indexOf(quote, 1)
    let inner = value.slice(1, end < 0 ? undefined : end)
    if (quote === '"') {
      // Find the real closing quote (skipping escaped ones), then unescape.
      let i = 1
      let out = ''
      for (; i < value.length; i++) {
        const ch = value[i]
        if (ch === '\\' && i + 1 < value.length) {
          const next = value[++i]
          out += next === 'n' ? '\n' : next === 'r' ? '\r' : next === 't' ? '\t' : next
          continue
        }
        if (ch === '"') break
        out += ch
      }
      inner = out
    }
    return inner
  }
  const comment = value.search(/\s#/)
  return (comment < 0 ? value : value.slice(0, comment)).trim()
}

/** Parse `.env` text. Never throws. */
export function parseEnv(text: string): EnvFile {
  const entries = new Map<string, EnvEntry>()
  const duplicates = new Set<string>()
  const all: EnvEntry[] = []
  const invalid: { line: number }[] = []
  const lines = text.replace(/^\uFEFF/, '').split(/\r?\n/)
  lines.forEach((raw, index) => {
    const trimmed = raw.trim()
    if (trimmed === '' || trimmed.startsWith('#')) return
    const match = ASSIGNMENT.exec(raw)
    const key = match?.[1]
    if (match === null || key === undefined) {
      invalid.push({ line: index + 1 })
      return
    }
    if (entries.has(key)) duplicates.add(key)
    const entry = { key, value: unquote(match[2] ?? ''), line: index + 1 }
    entries.set(key, entry)
    all.push(entry)
  })
  return { entries, all, duplicates: [...duplicates].sort(), invalid }
}

/** Read and parse a file; `undefined` if it does not exist. */
export function readEnvFile(path: string): EnvFile | undefined {
  if (!existsSync(path)) return undefined
  return parseEnv(readFileSync(path, 'utf8'))
}
